function showMulligan(){let p=game.sides.player;modal(`<h2>初手交換</h2><p>交換するカードを選択（1回だけ）。先攻：${name(game.firstSide)}</p><div>${p.hand.map((id,i)=>`<div class="mulliganCard" data-i="${i}">${K[id].name}<br><small>ENERGY ${K[id].cost}</small></div>`).join('')}</div><button id="mulliganDone">対戦開始</button>`);$('dialog').querySelectorAll('.mulliganCard').forEach(el=>el.onclick=()=>el.classList.toggle('on'));$('mulliganDone').onclick=()=>{let indices=[...$('dialog').querySelectorAll('.mulliganCard.on')].map(e=>+e.dataset.i);game.mulligan('player',indices);let h=game.sides.cpu.hand,ii=h.map((id,i)=>K[id].cost>4||id==='rescue'?i:-1).filter(i=>i>=0).slice(0,2);game.mulligan('cpu',ii);window.HumanPlaytest?.initialHands(game,indices);window.HumanPlaytest?.ui('mulligan',{indices});guideActive=localStorage.getItem('tactics7_beginner_guide')!=='done';closeModal();render();banner(game.turn==='player'?'YOUR TURN':'ENEMY TURN');if(game.turn==='cpu')cpuTurn()}}
