function status(s){let p=game.sides[s],comm=game.units.find(u=>u.side===s&&u.classId==='commander'),unlock=game.evolutionUnlocked(s),limit=R.evolution.unlockTurn[s===game.firstSide?'first':'second'],left=Math.max(0,limit-p.ownTurn),backCount=Math.min(7,p.hand.length);return `<div class="leaderSlot ${s}" title="${s==='player'?'PLAYER':'ENEMY'} LEADER = COMMANDER"><span class="leaderSilhouette">♛</span><small>${s==='player'?'PLAYER':'ENEMY'}<br>LEADER</small></div><div class="commanderHud ${s}"><span class="crown">♛</span><span><small>${s==='player'?'YOUR':'ENEMY'} LEADER / COMMANDER</small><strong>${comm.hp}<em>/${comm.maxHp}</em></strong></span></div><div class="resource energy" title="ENERGY ${p.energy}/${p.turnEnergyCap} · 基本最大${p.maxEnergy}"><span class="resourceLabel">ENERGY <b>${p.energy}/${p.turnEnergyCap}</b></span><span class="orbs">${Array.from({length:R.energy.cap+game.config.centerBonus},(_,i)=>`<i class="${i<p.energy?'full':''}"></i>`).join('')}</span></div><div class="resource ep" title="EP ${p.ep} · ${unlock?'進化可能':`解禁まで${left}ターン`}"><span class="resourceLabel">EP <b>${p.ep}</b></span><span class="epMarks">${Array.from({length:R.evolution.ep[s===game.firstSide?'first':'second']},(_,i)=>`<i class="${i<p.ep?'full':''}">◆</i>`).join('')}</span><small>${unlock?'進化可':`あと${left}T`}</small></div>${s==='cpu'?`<div class="enemyHandCards" title="相手の手札 ${p.hand.length}枚">${Array.from({length:backCount},()=>'<span class="miniBack">T7</span>').join('')}<small>×${p.hand.length}</small></div>`:''}<button class="deckStack ${p.deck.length?'':'empty'}" data-side="${s}" style="--stack:${Math.min(3,Math.ceil(p.deck.length/7))}" title="${name(s)}の山札 ${p.deck.length}枚"><span class="cardBack">T7</span><small>×${p.deck.length}</small></button><button class="graveStack ${p.graveyard.length?'hasCards':''} ${p.graveyard.length>1?'many':''}" data-grave="${s}" title="${name(s)}の墓地 ${p.graveyard.length}枚"><span class="graveFace">✦</span><small>×${p.graveyard.length}</small></button>`}
function armCard(){if(cardIndex==null)return;let reason=cardReason(cardIndex);if(reason){toast(reason);render();return}cardArmed=true;detailOpen=false;render()}

function instruction(){if(game.pending){let e=game.pending.effect;return e==='strikeTarget'?'進化：攻撃する敵を選択してください':flow?.stage==='target'?'進化：動かす対象を選択してください':'進化：効果の着地点を選択してください'}if(evolveMode)return '◆ 進化する味方を選択（EP 1消費）';if(game.turn==='cpu')return 'CPUが行動中です';if(cardIndex!=null){let id=game.sides.player.hand[cardIndex];if(!cardArmed)return `${K[id].name}：もう一度タップで使用`;let reason=cardReason(cardIndex);if(reason)return `${K[id].name}：${reason}`;if(K[id].type==='unit')return `${K[id].name}：召喚位置を選択してください`;if(flow?.stage==='source')return `${K[id].name}：最初の味方を選択してください`;if(flow?.stage==='target')return `${K[id].name}：次の対象を選択してください`;if(flow?.stage==='attackTarget')return `${K[id].name}：攻撃対象を選択してください`;return `${K[id].name}：着地点を選択してください`}let u=unit(selected);if(u?.side==='cpu')return `${C[u.classId].name}：黄＝移動候補、斜線＝現在の攻撃範囲（移動後は含まない）`;if(u){if(mode==='attack')return `${C[u.classId].name}：赤い攻撃対象を選択してください`;if(mode==='charge')return flow?.stage==='attackTarget'?`${C[u.classId].name}：突撃する敵を選択してください`:`${C[u.classId].name}：突撃先を選択してください`;return `${C[u.classId].name}：青い移動先か赤い攻撃対象を選択してください`}return 'ユニットまたは手札を選択してください'}
function playerOptions(){if(!game||game.phase!=='battle'||game.winner||game.turn!=='player'||decision)return[];if(game.pending){let p=game.pending,opts=p.options;if(flow?.kind==='pending'&&flow.stage==='dest')return opts.filter(o=>o.target===flow.target).map(o=>({x:o.x,y:o.y,kind:'evolve',opt:o}));if(opts.some(o=>o.target!=null))return unique(opts,o=>o.target).map(o=>({x:unit(o.target).x,y:unit(o.target).y,kind:'evolveTarget',target:o.target}));return opts.map(o=>({x:o.x,y:o.y,kind:'evolve',opt:o}))}
 if(cardIndex!=null){let id=game.sides.player.hand[cardIndex];if(!cardArmed||cardReason(cardIndex))return[];if(K[id].type==='unit')return game.summonZones('player').map(p=>({...p,kind:'summon'}));let opts=game.spellOptions(id,'player');if(K[id].spellKind){if(opts[0]?.unit==null)return unique(opts,o=>o.x+','+o.y).map(o=>({x:o.x,y:o.y,kind:'labDest',opt:o}));if(flow?.stage==='source')return unique(opts.map(o=>o.unit),v=>v).map(v=>({x:unit(v).x,y:unit(v).y,kind:'source',target:v}));if(flow?.stage==='target')return unique(opts.filter(o=>o.unit===flow.unit&&o.target!=null),o=>o.target).map(o=>({x:unit(o.target).x,y:unit(o.target).y,kind:'target',target:o.target,preview:o.x!=null?(K[id].spellKind==='breach'?`味方 → ${coord(unit(o.target))} / 敵 → ${coord(o)}`:K[id].spellKind==='barrage'?`敵に1ダメージ → ${coord(o)}`:`${coord(unit(o.target))} → ${coord(o)}`):`${coord(unit(flow.unit))} ⇄ ${coord(unit(o.target))}`,dest:o.x!=null?{x:o.x,y:o.y}:null}));return unique(opts.filter(o=>o.unit===flow?.unit),o=>o.x+','+o.y).map(o=>({x:o.x,y:o.y,kind:'spellDest'}))}if(flow?.stage==='source')return unique(id==='swap'?opts.flatMap(o=>[o.unit,o.target]):opts.map(o=>o.unit),v=>v).map(v=>({x:unit(v).x,y:unit(v).y,kind:'source',target:v}));if(flow?.stage==='target'){let matching=opts.filter(o=>o.unit===flow.unit||id==='swap'&&o.target===flow.unit);return unique(matching.map(o=>o.unit===flow.unit?o.target:o.unit),v=>v).map(v=>({x:unit(v).x,y:unit(v).y,kind:'target',target:v}))}if(flow?.stage==='attackTarget')return opts.filter(o=>o.unit===flow.unit&&o.x===flow.x&&o.y===flow.y&&o.target).map(o=>({x:unit(o.target).x,y:unit(o.target).y,kind:'attack',opt:o}));return unique(opts.filter(o=>o.unit===flow?.unit),o=>o.x+','+o.y).map(o=>({x:o.x,y:o.y,kind:'spellDest'}))}
 if(evolveMode)return game.units.filter(v=>v.side==='player'&&game.canEvolve(v)).map(v=>({x:v.x,y:v.y,kind:'evolveChoice',target:v.id}));
 let u=unit(selected);if(!u||u.side!=='player'||!game.canAct(u))return[];if(mode==='attack')return game.canAttack(u)?game.targets(u).map(v=>({x:v.x,y:v.y,kind:'attack',target:v.id})):[];if(mode==='charge'){if(!game.canAttack(u)||u.sick)return[];if(flow?.stage==='attackTarget')return game.units.filter(v=>v.side==='cpu'&&v.state==='active'&&Math.max(Math.abs(v.x-flow.x),Math.abs(v.y-flow.y))===1).map(v=>({x:v.x,y:v.y,kind:'attack',target:v.id}));return game.neighbors(u).filter(p=>game.free(p.x,p.y)&&game.units.some(v=>v.side==='cpu'&&v.state==='active'&&Math.max(Math.abs(v.x-p.x),Math.abs(v.y-p.y))===1)).map(p=>({...p,kind:'charge'}))}return [...game.moves(u).map(p=>({...p,kind:Math.max(Math.abs(p.x-u.x),Math.abs(p.y-u.y))>1?'specialMove':'move'})),...(game.canAttack(u)?game.targets(u).map(v=>({x:v.x,y:v.y,kind:'attack',target:v.id})):[])]}
function threatOptions(u){if(!u||u.side!=='cpu'||u.state!=='active')return[];if(u.sick&&game.config.summonTempo==='immobile')return[];let out=game.moves(u).map(p=>({...p,kind:'threatMove'}));if(u.sick)return out;for(let y=0;y<7;y++)for(let x=0;x<7;x++){let occupant=game.at(x,y);if(game.terrain(x,y)==='#'||occupant?.side===u.side)continue;let fake={x,y,side:'player',state:'active'},info=game.attackInfo(u,fake);if(info)out.push({x,y,kind:'threatAttack',info})}return out}
function forecast(target,n){let d=game.previewDamage(target,n);return `威力 ${d.base}${d.reduction?` · 防御 −${d.reduction}`:''} → <b>実ダメージ ${d.actual}</b><br>${C[target.classId].name} HP ${d.before} → ${d.after}${d.down?' · DOWN':''}${target.classId==='commander'&&d.down?' · 勝利':''}`}
function attackUnavailable(a,b){if(a.sick&&!K[a.cardId]?.rush)return'召喚ターンは攻撃不可';if(a.sick&&b.classId==='commander')return'突進はCOMMANDERへ使用不可';if(!game.canAct(a))return a.sick?'召喚酔い':a.acted?'行動済み':'行動できません';if(b.state!=='active')return'DOWN中';let d=Math.max(Math.abs(a.x-b.x),Math.abs(a.y-b.y)),c=C[a.classId];if(d>c.range)return'射程外';if(d===1)return'攻撃可能';if(game.neighbors(a).some(p=>game.at(p.x,p.y)?.side==='cpu'&&game.at(p.x,p.y)?.state==='active'))return'敵に隣接中のため射撃不可';if(c.line==='straight'&&a.x!==b.x&&a.y!==b.y)return'直線上のみ攻撃可能';let dx=b.x-a.x,dy=b.y-a.y,n=Math.max(Math.abs(dx),Math.abs(dy));if(dx!==0&&dy!==0&&Math.abs(dx)!==Math.abs(dy))return'射線が通らない';let sx=Math.sign(dx),sy=Math.sign(dy),rocks=0;for(let i=1;i<n;i++){let x=a.x+sx*i,y=a.y+sy*i;if(game.at(x,y))return'ユニットが遮断';if(game.terrain(x,y)==='#')rocks++}if(rocks>(c.line==='oneObstacle'?1:0))return'障害物が遮断';return'攻撃できません'}
function attackBadge(target,n){let d=game.previewDamage(target,n);return `<span class="attackForecast ${d.down?'fatal':''}"><b>${target.classId==='commander'&&d.down?'LETHAL / 勝利':`${d.actual} DAMAGE`}</b><small>威力${d.base}${d.reduction?` − 防御${d.reduction}`:''} · HP ${d.before} → ${d.down?'DOWN':d.after}</small></span>`}
function summonEffect(card,place){if(card.onSummon==='stepForward'){let next={x:place.x,y:place.y-1};return game.free(next.x,next.y)?`登場時：${coord(place)} → ${coord(next)} に前進`:'登場時前進：前方が塞がれているため発動なし'}if(card.onSummon==='guardAdjacent'){let allies=game.neighbors(place).map(p=>game.at(p.x,p.y)).filter(v=>v&&v.side==='player'&&v.state==='active').sort((a,b)=>a.hp-b.hp);return allies.length?`登場時：${C[allies[0].classId].name}に防御 +1`:'登場時防御：隣接する味方なし'}if(card.onSummon==='royalDraw'&&game.sides.player.royalDown)return '登場時：1ドロー';return''}
function confirmAction(title,detail,run,points={}){let ok=perform(run,{message:title,points});if(ok&&game.pending&&!flow){flow={kind:'pending',stage:'target'};render()}return ok}
function selectCard(i,inputType){if(cardIndex===i){if(!cardArmed)armCard();else{cardArmed=false;detailOpen=true;render()}return}cardIndex=i;cardArmed=false;detailOpen=true;evolveMode=false;selected=null;mode='move';decision=null;let id=game.sides.player.hand[i];flow=K[id].type==='spell'?{kind:'spell',stage:'source'}:null;if(inputType!=='touch'&&matchMedia('(hover:hover) and (pointer:fine)').matches)armCard();else render()}
function summonCardAt(index,o,inputMethod='click'){let id=game?.sides.player.hand[index],c=K[id],legal=game&&c?.type==='unit'&&!cardReason(index)&&game.summonZones('player').some(p=>p.x===o.x&&p.y===o.y);if(!legal)return false;let cl=C[c.classId],energy=game.sides.player.energy,effect=summonEffect(c,o),detail=`${c.name}を ${coord(o)} に召喚<br>ENERGY ${energy} → ${energy-c.cost}<br>HP ${cl.hp} · 召喚酔い${effect?`<br>${effect}`:''}`;return perform(()=>{let result=game.summon('player',index,o.x,o.y);if(result){cardIndex=null;cardArmed=false;detailOpen=false;flow=null}return result},{message:'召喚',detail,points:{to:o},inputMethod})}
function clearCardDrag(cancelled=false){if(!cardDrag)return;clearTimeout(cardDrag.hold);cardDrag.ghost?.remove();document.body.classList.remove('cardDragging');document.querySelectorAll('.drag-legal,.drag-hover').forEach(el=>el.classList.remove('drag-legal','drag-hover'));if(cancelled&&cardDrag.active)window.HumanPlaytest?.ui('dragCancel',{cardId:cardDrag.id,inputMethod:'drag'});cardDrag=null}
function dragTarget(clientX,clientY){let cell=document.elementFromPoint(clientX,clientY)?.closest('.cell');if(!cell||!cardDrag)return null;let x=+cell.dataset.x,y=+cell.dataset.y;return cardDrag.legal.some(p=>p.x===x&&p.y===y)?{cell,x,y}:null}
function startCardDrag(e,el,i,id,hold){if((e.pointerType==='mouse'&&e.button!==0)||!game)return;cardDrag={pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,el,i,id,hold,active:false,long:false,legal:[]};try{el.setPointerCapture(e.pointerId)}catch{}}
function moveCardDrag(e){let d=cardDrag;if(!d||d.pointerId!==e.pointerId||d.long)return;let threshold=e.pointerType==='touch'?10:7;if(!d.active&&Math.hypot(e.clientX-d.startX,e.clientY-d.startY)<threshold)return;if(!d.active){if(K[d.id]?.type!=='unit'||cardReason(d.i))return;clearTimeout(d.hold);d.active=true;d.legal=game.summonZones('player');if(!d.legal.length)return clearCardDrag(true);d.el.dataset.dragged='1';document.body.classList.add('cardDragging');d.legal.forEach(p=>$('board').querySelector(`[data-x="${p.x}"][data-y="${p.y}"]`)?.classList.add('drag-legal'));d.ghost=d.el.cloneNode(true);d.ghost.removeAttribute('id');d.ghost.className='cardDragGhost';document.body.appendChild(d.ghost);window.HumanPlaytest?.ui('dragStart',{cardId:d.id,inputMethod:'drag'})}e.preventDefault();d.ghost.style.left=(e.clientX+14)+'px';d.ghost.style.top=(e.clientY-56)+'px';document.querySelectorAll('.drag-hover').forEach(v=>v.classList.remove('drag-hover'));dragTarget(e.clientX,e.clientY)?.cell.classList.add('drag-hover')}
function endCardDrag(e,cancelled=false){let d=cardDrag;if(!d||d.pointerId!==e.pointerId)return;clearTimeout(d.hold);if(!d.active){cardDrag=null;return}e.preventDefault();let target=cancelled?null:dragTarget(e.clientX,e.clientY),index=d.i;clearCardDrag(!target);if(target)summonCardAt(index,target,'drag');setTimeout(()=>{if(d.el)d.el.dataset.dragged=''},0)}
function handleOption(o){if(o.kind==='evolveChoice'){let v=unit(o.target);evolveMode=false;confirmAction('進化',`EP 1消費 · ${evoText(C[v.classId].evolution)}`,()=>{let ok=game.evolve(v.id);if(ok&&game.pending)flow={kind:'pending',stage:'target'};return ok},{from:v,to:v});return}if(game.pending){let p=game.pending;if(o.kind==='evolveTarget'&&p.options.some(v=>v.x!=null&&v.target===o.target)){flow={kind:'pending',stage:'dest',target:o.target};render();return}let opt=o.opt||p.options.find(v=>v.target===o.target);let actor=unit(p.unit),target=opt.target&&unit(opt.target),detail=`${C[actor.classId].name}：${evoText(p.effect)}`;if(opt.x!=null)detail+=`<br>${target?C[target.classId].name:coord(actor)} → ${coord(opt)}`;if(p.effect==='strikeTarget'&&target)detail+=`<br>${forecast(target,1)}`;confirmAction('進化効果',detail,()=>game.resolvePending(opt),{from:actor,to:target||opt});return}
 if(cardIndex!=null){let id=game.sides.player.hand[cardIndex],c=K[id],energy=game.sides.player.energy;if(c.type==='unit'){summonCardAt(cardIndex,o,'click');return}
 let opts=game.spellOptions(id,'player');if(c.spellKind){if(o.kind==='labDest'){confirmSpell(id,o.opt);return}if(o.kind==='source'){let matching=opts.filter(v=>v.unit===o.target);flow={kind:'spell',unit:o.target,stage:matching.some(v=>v.target!=null)?'target':matching.some(v=>v.x!=null)?'dest':'ready'};if(flow.stage==='ready'){confirmSpell(id,matching[0]);return}render();return}if(o.kind==='target'){confirmSpell(id,opts.find(v=>v.unit===flow.unit&&v.target===o.target));return}if(o.kind==='spellDest'){confirmSpell(id,opts.find(v=>v.unit===flow.unit&&v.x===o.x&&v.y===o.y));return}}if(o.kind==='source'){flow={kind:'spell',stage:id==='rescue'?'ready':id==='swap'?'target':'dest',unit:o.target};if(id==='rescue'){confirmSpell(id,opts.find(v=>v.unit===o.target));return}render();return}if(o.kind==='target'){let opt=opts.find(v=>(v.unit===flow.unit&&v.target===o.target)||(v.target===flow.unit&&v.unit===o.target));confirmSpell(id,opt);return}if(o.kind==='spellDest'){let matches=opts.filter(v=>v.unit===flow.unit&&v.x===o.x&&v.y===o.y);let attacks=matches.filter(v=>v.target);if(attacks.length>1){flow={...flow,stage:'attackTarget',x:o.x,y:o.y};render();return}confirmSpell(id,matches[0]);return}if(o.kind==='attack')confirmSpell(id,o.opt);return}
 let a=unit(selected);if(!a)return;if(o.kind==='attack'&&mode!=='charge'){let target=unit(o.target),info=game.attackInfo(a,target);confirmAction(`${info.type}攻撃`,`${C[a.classId].name} ${coord(a)} → ${C[target.classId].name} ${coord(target)}<br>${forecast(target,info.damage)}`,()=>game.attack(a.id,target.id),{from:a,to:target,damage:info.damage});return}if(mode==='charge'){if(o.kind==='charge'){flow={kind:'charge',stage:'attackTarget',x:o.x,y:o.y};render();return}let target=unit(o.target);confirmAction('突撃',`${C[a.classId].name} ${coord(a)} → ${coord(flow)}<br>${forecast(target,1)}`,()=>game.charge(a.id,flow.x,flow.y,target.id),{from:a,to:target,damage:1});return}confirmAction('移動',`${C[a.classId].name} ${coord(a)} → ${coord(o)}`,()=>game.move(a.id,o.x,o.y),{from:a,to:o})}
