function cpuStep(){let s='cpu',p=game.sides.cpu;if(game.pending){let o=game.pending.options[0];game.resolvePending(o);return true}if(game.evolutionUnlocked(s)&&p.ep){let candidates=game.units.filter(u=>u.side===s&&u.state==='active'&&!u.evolved&&u.classId!=='commander');candidates.sort((a,b)=>({knight:5,mage:5,archer:4,tank:4,guard:3,spearman:3,recruit:1})[b.classId]-({knight:5,mage:5,archer:4,tank:4,guard:3,spearman:3,recruit:1})[a.classId]);if(candidates.length&&game.evolve(candidates[0].id))return true}
 let cards=p.hand.map((id,i)=>({id,i,c:K[id]})).filter(v=>game.cardPlayable(s,v.i));let rescue=cards.find(v=>v.id==='rescue'&&game.spellOptions(v.id,s).length);if(rescue){game.playSpell(s,rescue.i,game.spellOptions(rescue.id,s)[0]);return true}
 let affordable=cards.filter(v=>v.c.type==='unit'&&game.summonZones(s).length);affordable.sort((a,b)=>{let sa=(a.id==='recruit'&&game.sides.cpu.ownTurn<=3?5:0)+a.c.cost,sb=(b.id==='recruit'&&game.sides.cpu.ownTurn<=3?5:0)+b.c.cost;return sb-sa});if(affordable.length){let v=affordable[0],zones=game.summonZones(s);zones.sort((a,b)=>Math.max(Math.abs(a.x-3),Math.abs(a.y-3))-Math.max(Math.abs(b.x-3),Math.abs(b.y-3)));let z=zones.find(q=>!game.units.some(u=>u.side==='player'&&u.state==='active'&&Math.max(Math.abs(q.x-u.x),Math.abs(q.y-u.y))===1))||zones[0];game.summon(s,v.i,z.x,z.y);return true}
 let spell=cards.find(v=>v.c.type==='spell'&&v.id!=='rescue'&&game.spellOptions(v.id,s).length);if(spell&&p.energy>=4){let opts=game.spellOptions(spell.id,s);if(spell.id==='breakthrough')opts.sort((a,b)=>scoreMove(unit(b.unit),b)-scoreMove(unit(a.unit),a));game.playSpell(s,spell.i,opts[0]);return true}
 if(game.used>=R.actionsPerTurn)return false;let choices=[];for(const u of game.units.filter(u=>game.canAct(u))){for(const e of game.canAttack(u)?game.targets(u):[]){let info=game.attackInfo(u,e),score=8+info.damage*2+(e.hp<=info.damage?15:0)+(e.classId==='commander'?25:0);choices.push({score,go:()=>game.attack(u.id,e.id)})}for(const q of game.moves(u)){let score=scoreMove(u,q);choices.push({score,go:()=>game.move(u.id,q.x,q.y)})}for(const q of (game.canAttack(u)&&!u.sick?game.neighbors(u).filter(q=>game.free(q.x,q.y)):[]))for(const e of game.units.filter(e=>e.side==='player'&&e.state==='active'&&Math.max(Math.abs(e.x-q.x),Math.abs(e.y-q.y))===1)){choices.push({score:scoreMove(u,q)+7+(e.hp===1?12:0),go:()=>game.charge(u.id,q.x,q.y,e.id)})}}choices.sort((a,b)=>b.score-a.score);if(choices.length&&choices[0].score>-7)return choices[0].go();return false}
async function cpuTurn(){if(cpuBusy)return;cpuBusy=true;let match=game,count=0;while(game===match&&game.turn==='cpu'&&game.phase==='battle'&&!game.winner&&count++<35){let before=snapshot(),a=window.CoreAI.choose(game,'cpu','Balanced','Strong'),ok=window.CoreAI.apply(game,'cpu',a);if(!ok)break;render();animateChanges(before,{message:'CPUの行動'});let wait=+$('cpuSpeed').value;if(wait)await new Promise(r=>setTimeout(r,wait))}if(game!==match)return;if(game.turn==='cpu'&&!game.winner){if(game.pending)game.resolvePending(null);perform(()=>game.endTurn(),{message:'ターン終了'})}cpuBusy=false;render()}
function panel(id){for(const v of ['infoPanel','logPanel','gravePanel','debugPanel'])$(v).hidden=v!==id||!$(v).hidden}
$('infoToggle').onclick=()=>panel('infoPanel');$('logToggle').onclick=()=>panel('logPanel');$('graveToggle').onclick=()=>panel('gravePanel');$('debugToggle').onclick=()=>panel('debugPanel');
$('debugToggle').hidden=new URLSearchParams(location.search).get('dev')!=='1';
 $('cardDetailToggle').onclick=detailSelected;$('closeCardDetail').onclick=closeCardDetail;document.addEventListener('pointerdown',e=>{if(!$('cardDetailPanel').hidden&&!e.target.closest('#cardDetailPanel')&&!e.target.closest('#cardDetailToggle')){if(e.target.closest('#board'))$('board').dataset.dismissDetail='1';closeCardDetail()}},true);$('board').addEventListener('click',e=>{if($('board').dataset.dismissDetail){delete $('board').dataset.dismissDetail;e.preventDefault();e.stopImmediatePropagation()}},true);
for(const [button,id] of [['closeInfo','infoPanel'],['closeLog','logPanel'],['closeGrave','gravePanel'],['closeDebug','debugPanel']])$(button).onclick=()=>$(id).hidden=true;
$('guideSkip').onclick=()=>{guideActive=false;localStorage.setItem('tactics7_beginner_guide','done');$('beginnerGuide').hidden=true;document.body.classList.remove('guideHand','guideBoard','guideUnit','guideEvolve')};
window.addEventListener('tactics7-sync-status',e=>{let n=$('syncNotice');if(n&&e.detail?.matchId===window.HumanPlaytest?.active?.matchId)n.textContent=syncMessage(e.detail.status)});
document.addEventListener('pointermove',moveCardDrag,{passive:false});document.addEventListener('pointerup',e=>endCardDrag(e));document.addEventListener('pointercancel',e=>endCardDrag(e,true));
$('newGame').onclick=()=>{if(game&&!game.winner)window.HumanPlaytest?.finish(game,'abandoned');showDeck()};$('cancel').onclick=()=>cancel();$('board').oncontextmenu=e=>{e.preventDefault();if(!e.target.closest('.cell'))closeCardDetail()};document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('cardDetailPanel').hidden){closeCardDetail();return}if(!$('modal').hidden)return;for(const id of ['infoPanel','logPanel','gravePanel','debugPanel'])$(id).hidden=true;cancel()}});
$('endTurn').onclick=()=>{if(game.pending||decision)return;if(perform(()=>game.endTurn(),{message:'ターン終了'})){cancel(true);render();if(game.turn==='cpu')cpuTurn()}};
$('evolve').onclick=()=>{if(game.pending||game.turn!=='player')return;evolveMode=!evolveMode;cardIndex=null;cardArmed=false;flow=null;render()};
$('maxEp').onclick=()=>{game.sides.player.ep=2;render()};$('drawCard').onclick=()=>{perform(()=>game.draw('player')>0,{message:'カードをドロー'})};$('debugReset').onclick=()=>{if(game&&!game.winner)window.HumanPlaytest?.finish(game,'debugReset');showDeck()};
